<script setup lang="ts">
import { onMounted, onUnmounted, ref } from 'vue'
import { api } from '../../shared/api'
import { message, type Capabilities } from '../../shared/domain'
interface Notification {id:string;intent_id:string;title:string;message:string;activity_id:string;activity_version:number;state:string;kind:string}
interface Rules {user_id?:string;version:number;reminders:boolean;progress:boolean;results:boolean;channels:string[];lead_minutes:number;result_delay_minutes:number;progress_minutes:number;daily_limit:number;repeat_count:number;repeat_minutes:number;tone:string;message_format:string}
interface Link {connected:boolean;pending:{id:string;candidate_id:number|null;expires_at:string}[]}
const rows=ref<Notification[]>([]),rules=ref<Rules|null>(null),cap=ref<Capabilities|null>(null),link=ref<Link|null>(null)
const error=ref(''),busy=ref(false),url=ref(''),saved=ref('')
const tones=['спокойный','нейтральный','поддерживающий']
let timer:ReturnType<typeof setInterval>|undefined
async function load(){rows.value=await api<Notification[]>('/api/v1/notifications');link.value=await api<Link>('/api/v1/telegram/link')}
async function run(action:()=>Promise<unknown>){if(busy.value)return;busy.value=true;error.value='';saved.value='';try{await action();await load()}catch(e){error.value=message(e)}finally{busy.value=false}}
async function save(){await run(async()=>{const {user_id:_,...body}=rules.value!;rules.value=await api<Rules>('/api/v1/notifications/rules',{method:'PUT',body});saved.value='Правила сохранены.'})}
async function answer(n:Notification,outcome:string){await run(()=>api('/api/v1/activities/'+n.activity_id+'/result',{method:'POST',body:{version:n.activity_version,outcome,intent_id:n.intent_id}}))}
async function push(){await run(async()=>{
  if(!('serviceWorker'in navigator)||!('PushManager'in window))throw new Error('Этот браузер не поддерживает Web Push.')
  if(await Notification.requestPermission()!=='granted')throw new Error('Разрешение на уведомления не получено. Их можно читать здесь.')
  const registration=await navigator.serviceWorker.register('/sw.js')
  await navigator.serviceWorker.ready
  const key=cap.value!.vapid_public_key.replace(/-/g,'+').replace(/_/g,'/')
  const bytes=Uint8Array.from(atob(key+'='.repeat((4-key.length%4)%4)),c=>c.charCodeAt(0))
  const subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:bytes})
  const data=subscription.toJSON()
  await api('/api/v1/push/subscriptions',{method:'POST',body:{endpoint:data.endpoint,p256dh:data.keys?.p256dh,auth:data.keys?.auth}})
  saved.value='Уведомления для этого браузера включены.'
})}
onMounted(async()=>{await run(async()=>{rules.value=await api<Rules>('/api/v1/notifications/rules');cap.value=await api<Capabilities>('/api/v1/capabilities')});timer=setInterval(()=>{void load().catch(()=>{})},15000)})
onUnmounted(()=>{if(timer)clearInterval(timer)})
</script>
<template><section class="page wide-page"><p class="eyebrow">СОПРОВОЖДЕНИЕ</p><h1>В нужный момент.</h1><p class="lead">Обращения остаются здесь, даже если внешний канал недоступен.</p><p v-if="error" class="notice" role="alert">{{error}}</p><p v-if="saved" class="success-note" role="status">{{saved}}</p>
  <div class="form-card"><h2>Уведомления</h2><button class="secondary-button" :disabled="busy" @click="run(load)">Обновить</button><p v-if="!rows.length" class="quiet-note">Пока нет обращений.</p><article v-for="n in rows" :key="n.id" class="domain-row"><h3>{{n.title}}</h3><p class="prose-text">{{n.message}}</p><div v-if="n.state==='delivered'" class="toolbar"><button :disabled="busy" @click="answer(n,'done')">Сделал</button><button class="secondary-button" :disabled="busy" @click="answer(n,'partial')">Частично</button><button class="secondary-button" :disabled="busy" @click="run(()=>api('/api/v1/notifications/'+n.intent_id+'/later',{method:'POST',body:{minutes:60}}))">Позже</button><button class="secondary-button" :disabled="busy" @click="answer(n,'cancelled')">Отменил</button></div><p v-else class="field-note">{{n.state==='answered'?'Ответ записан':n.state==='pending'?'Отложено':'Обращение закрыто'}}</p></article></div>
  <form v-if="rules" class="form-card form-stack" @submit.prevent="save"><h2>Правила сопровождения</h2><label class="checkbox-label"><input v-model="rules.reminders" type="checkbox">Напоминать до начала</label><label class="checkbox-label"><input v-model="rules.progress" type="checkbox">Спрашивать о прогрессе</label><label class="checkbox-label"><input v-model="rules.results" type="checkbox">Спрашивать о результате</label><div class="form-grid"><label>За сколько минут до начала<input v-model.number="rules.lead_minutes" type="number" min="0" max="10080" required></label><label>Через сколько минут после конца<input v-model.number="rules.result_delay_minutes" type="number" min="0" max="10080" required></label><label>Прогресс через минут<input v-model.number="rules.progress_minutes" type="number" min="1" max="10080" required></label><label>Не больше обращений в день<input v-model.number="rules.daily_limit" type="number" min="0" max="100" required></label><label>Повторов без ответа<input v-model.number="rules.repeat_count" type="number" min="0" max="5" required></label><label>Между повторами, минут<input v-model.number="rules.repeat_minutes" type="number" min="1" max="10080" required></label><label>Тон<select v-model="rules.tone"><option v-for="tone in tones" :key="tone" :value="tone">{{tone}}</option></select></label><label>Формат<select v-model="rules.message_format"><option>кратко</option><option>с подробностями</option></select></label></div><p class="field-note">Тихие часы, часовой пояс и пауза — в настройках профиля. Отдельную активность можно настроить в плане.</p><fieldset><legend>Каналы</legend><label class="checkbox-label"><input type="checkbox" checked disabled>Центр уведомлений в вебе</label><label class="checkbox-label"><input v-model="rules.channels" type="checkbox" value="push" :disabled="!cap?.push">Web Push {{!cap?.push?'— сервер ещё не настроен':''}}</label><label class="checkbox-label"><input v-model="rules.channels" type="checkbox" value="telegram" :disabled="!cap?.telegram">Telegram {{!cap?.telegram?'— бот ещё не настроен':''}}</label></fieldset><button :disabled="busy">Сохранить правила</button></form>
  <div class="form-card"><h2>Подключения</h2><p class="field-note">Web Push: {{cap?.push?'доступен для подключения':'пока не настроен'}}. Голос: {{cap?.voice?'доступен в Telegram':'распознавание ещё не подключено'}}.</p><div class="toolbar"><button v-if="cap?.push" :disabled="busy" @click="push">Включить Web Push</button><button class="secondary-button" :disabled="busy" @click="run(()=>api('/api/v1/push/subscriptions',{method:'DELETE'}))">Отключить Push</button></div><h3>Telegram</h3><p v-if="!cap?.telegram" class="field-note">Для подключения нужен настроенный бот с webhook.</p><p v-else-if="link?.connected">Аккаунт подключён.</p><button v-if="cap?.telegram&&!link?.connected" :disabled="busy" @click="run(async()=>{const data=await api<{link:string}>('/api/v1/telegram/link',{method:'POST'});url=data.link})">Получить ссылку</button><p v-if="url"><a :href="url" target="_blank" rel="noopener noreferrer" class="text-link">Открыть бота в Telegram</a></p><div v-for="p in link?.pending" :key="p.id"><p class="field-note">{{p.candidate_id?'Telegram найден. Подтвердите, что это ваш аккаунт.':'Откройте ссылку, нажмите «Запустить» у бота, затем обновите статус.'}}</p><div class="toolbar"><button v-if="p.candidate_id" :disabled="busy" @click="run(()=>api('/api/v1/telegram/link/'+p.id+'/confirm',{method:'POST'}))">Подтвердить привязку</button><button class="secondary-button" @click="run(load)">Обновить статус</button></div></div><button v-if="link?.connected" class="secondary-button" :disabled="busy" @click="run(()=>api('/api/v1/telegram/link',{method:'DELETE'}))">Отключить Telegram</button></div>
</section></template>
